import {section,table,cite,topic,mountTopic,rangePlayback} from './topic-tools.js';
import {texEq as eq,inlineMath} from './math.js';
import {loss,allocation,mixedDerivative,effectiveData,gapFrames,demoLaw} from './scaling-model.js';
const budgetTable=(...args)=>table(...args).replace('<table>','<table style="min-width:640px">');
const residualFigure=`<figure class="stability-figure"><div class="stability-figure-meta"><b>Skaling Figure 1: signed residuals and relative error</b><a href="/img/scaling/skaling-residuals-v1.png" target="_blank" rel="noopener">Open full-size ↗</a></div><div class="stability-plot-scroll" tabindex="0" role="region" aria-label="Skaling residual plots; scroll horizontally for all three panels"><a href="/img/scaling/skaling-residuals-v1.png" target="_blank" rel="noopener" aria-label="Open full-size Skaling residual comparison"><img src="/img/scaling/skaling-residuals-v1.png" width="1320" height="375" alt="Three model-size versus token-budget grids: Chinchilla has opposing signed errors near the corners, Skaling residuals are smaller, and the third panel compares their error ratios." loading="lazy"></a></div><figcaption>Scroll horizontally to compare all three panels at a readable size. Read N horizontally and training tokens D vertically; both axes are logarithmic. Left and middle share a signed-error scale: red overestimates loss, blue underestimates it. The right panel instead shows an error ratio, capped at 16×. Its red points favor Skaling; they do not show a training speedup. Percentages summarize this reported grid, not all possible recipes. Cropped from Figure 1, Videau et al., arXiv v1 (CC BY 4.0); plot labels unchanged. ${cite('https://arxiv.org/pdf/2608.07222v1','Source PDF')}</figcaption></figure>`;
export const scalingMeta={slug:'training/scaling',title:'Scaling Laws',description:'Allocate parameters, data and compute; distinguish empirical frontiers, repetition, deployment objectives and coupled loss surfaces.',date:'2026-04-08',updated:'2026-10-18',topicPath:['training'],tags:['Chinchilla','Kaplan','Skaling','compute allocation','overtraining','repetition','efficiency gain','K BT'],learningGoals:['Derive the allocation under a stated cost model.','Separate unique data, processed samples and optimizer steps.','Evaluate extrapolation, coupling and floor uncertainty.'],related:['training/optimization','models/moe','training/parallelism'],prototype:true,visibility:'public',kind:'dense-topic'};
export const scalingAliases=['ai/training/scaling/scaling-laws','ai/training/scaling/data-constrained-scaling-laws','ai/training/scaling/overtraining-and-inference-aware-scaling','ai/training/scaling/decomposing-scaling-laws','ai/training/scaling/skaling-coupled-model-data-scaling-laws'];
export const scalingSections=[['question','Start with the objective'],['units','Name the quantities before fitting'],['power','Read a power law above its floor'],['kaplan','2020: capacity and sample efficiency'],['chinchilla','2022: balance capacity and tokens'],['allocation','Derive the fixed-compute optimum'],['budget-lab','Move along an equal-compute curve'],['counting','Why fitted frontiers disagree'],['estimates','Convert compute into a first budget'],['repetition','Count novelty separately from exposure'],['repeat-lab','Watch repeated tokens lose marginal value'],['penalties','Model memorization without extrapolating forever'],['sources-data','Make repetition source-specific'],['lifecycle','Change the objective, not the meaning of optimal'],['examples','Read heavy-training examples with their denominators'],['stages','Include the rest of the train–infer–think pipeline'],['gaps','Decompose the loss before proposing a law'],['gap-lab','Build the accounting identity'],['competing','One algebraic pattern connects the trade-offs'],['learning-rate','Balance travel and update precision'],['batch','K means processed samples, not unique data'],['size-optimization','Model size also changes the optimization terms'],['shape','Allocate width and depth under a parameter budget'],['compute-gaps','Balance optimized training and architecture'],['sparsity','Stored capacity does not replace active computation'],['memory-allocation','Divide storage between experts and memory'],['epochs','A local repetition penalty gives a fragile epoch rule'],['coefficients','Test slope changes instead of assuming them'],['coupling','2026: ask whether model and data interact'],['coupling-measurement','Convert log-coordinate derivatives correctly'],['coupling-lab','Compare marginal gains on the same surface'],['coupled-optimum','The outer exponent does not directly move the optimum'],['profiling','Use an L-shaped grid, then test its missing corner'],['evidence','Keep the Skaling comparisons and their scope'],['sk-grid-recipe','Keep the measured surface tied to its recipe'],['floor','The fitted floor is not measured entropy'],['fitting','Design a fit that can fail honestly'],['ladders','Compare curves, not one proxy winner'],['rl','RL scaling is a different resource problem'],['sources','References and connected notes']];
function budgetBody(step,k=1){const C=600,N=10**(step/25),D=C/(6*N),law={...demoLaw,k},opt=allocation(C),px=x=>45+Math.log10(x)*170,py=y=>230-Math.log10(y)*85;return `<svg viewBox="0 0 450 285" role="img" aria-label="Normalized parameter and token plane, logarithmic axes, compute 600; N ${N.toFixed(2)}, D ${D.toFixed(2)}"><path d="M45 35V230H400" fill="none" stroke="#93748a"/><path d="M45 60L385 230" stroke="#bd738e" stroke-width="3"/><circle cx="${px(N)}" cy="${py(D)}" r="7" fill="#bad6fa"/><circle cx="${px(opt.N)}" cy="${py(opt.D)}" r="11" fill="none" stroke="#eadbad"/><text x="45" y="25">D: normalized token units</text>${[1,10,100].map(x=>`<text x="${px(x)-5}" y="255">${x}</text><text x="8" y="${py(x)+6}">${x}</text>`).join('')}<text x="70" y="280">N: normalized parameter units</text></svg><p>N=${N.toFixed(3)}, D=${D.toFixed(3)}, 6ND=${C}. Loss=${loss(N,D,law).toFixed(4)}; best on this curve=${loss(opt.N,opt.D,law).toFixed(4)} at N=D=10. Blue: chosen point; gold ring: optimum.</p><p>Assigned ${inlineMath(String.raw`A=B=1`)}, ${inlineMath(String.raw`\alpha=\beta=0.4`)}, ${inlineMath(String.raw`E=1`)}. Both axes are logarithmic. Units are normalized, not billions of real parameters or tokens. The outer exponent ${inlineMath(String.raw`k=${k}`)} changes loss, not this fixed-inner-parameter optimum.</p>`;}
function repeatBody(r){const raw=1+r,effective=effectiveData(1,r,4),scale=340/17;return `<svg viewBox="0 0 440 210" role="img" aria-label="Unique corpus one unit, ${r} extra passes, raw tokens ${raw}, effective tokens ${effective.toFixed(3)}"><text x="25" y="30">Raw versus discounted token units</text><rect x="25" y="55" width="${raw*scale}" height="30" fill="#bd738e"/><rect x="25" y="120" width="${effective*scale}" height="30" fill="#bad6fa"/><text x="25" y="105">Raw: ${raw.toFixed(0)}</text><text x="25" y="180">Effective: ${effective.toFixed(3)}; ceiling 5</text></svg><p>U=1, r_D=4, R=${r}. Marginal effective tokens per extra pass: ${inlineMath(String.raw`\exp(-R/4)`)}=${Math.exp(-r/4).toFixed(3)}. No repetition gives D′=1. The ceiling is 1+4=5, not unlimited growth.</p><p>This is the assigned exponential-discount model, not a measured corpus or an overfitting curve. It can saturate; it cannot by itself make validation loss rise.</p>`;}
function gapBody(step,caseName){const values=caseName==='negative'?[1.7,2.2,1.8,1.4]:[2.5,2.2,1.8,1.4],frames=gapFrames(...values),visible=frames.slice(0,step),total=visible.reduce((s,f)=>s+f.value,0);let level=0;return `<svg viewBox="0 0 460 295" role="img" aria-label="Signed loss accounting through ${step} components; total ${total.toFixed(1)}">${visible.map((f,i)=>{const before=level;level+=f.value;const y=245-75*Math.max(before,level),height=75*Math.abs(f.value);return `<rect x="${35+i*100}" y="${y}" width="65" height="${height}" fill="${f.value<0?'#eadbad':i%2?'#bd738e':'#bad6fa'}"/><text x="${35+i*100}" y="275">${f.value.toFixed(1)}</text>`;}).join('')}<path d="M25 245H435" stroke="#93748a"/><text x="25" y="25">Floor → architecture → optimization → data</text><text x="25" y="50">Sum so far: ${total.toFixed(1)}</text></svg><p>${visible.map(f=>`${f.name}: ${f.value.toFixed(1)}`).join('; ')||'No components added yet.'}</p><p>Assigned training loss 2.2, best architecture loss 1.8, unrestricted training floor 1.4; target loss ${values[0]}. ${caseName==='negative'?'The target distribution is easier: the generalization difference is −0.5. The exact identity still holds.':'The target distribution is harder: the data difference is +0.3.'} These optima are conceptual in real neural training; the bars are not measured independent causes.</p>`;}
function couplingBody(power,k){const N=10,D=2**power,law={...demoLaw,k},gain=loss(N,D,law)-loss(2*N,D,law);return `${table('Assigned normalized law; double N=10 to N=20 at different data budgets',['D','Loss at N=10','Loss at N=20','Gain'],[1,4,16,64,256].map(d=>[d,loss(10,d,law).toFixed(4),loss(20,d,law).toFixed(4),(loss(10,d,law)-loss(20,d,law)).toFixed(4)]))}<p>Selected D=${D}; k=${k}: doubling capacity lowers loss by ${gain.toFixed(4)}. Mixed derivative at (10,${D})=${mixedDerivative(N,D,law).toExponential(3)}.</p><p>${k===1?'The gain is the same at every D: the additive law forces zero mixed derivative.':k<1?'The gain grows with D: a negative mixed derivative describes complementarity.':'The gain shrinks with D: positive mixed derivative describes diminishing cross-resource benefit.'} Inner parameters are held fixed. Different absolute losses between k values are not fitted evidence of which law is better.</p>`;}
function lab(id,title,intro,controls,body,play=false){return `<div class="topic-scene" data-scaling-lab="${id}"><h3>${title}</h3><p>${intro}</p>${controls}${play?'<div class="dense-actions"><button data-play type="button">Play</button><button data-reset type="button">Replay</button></div>':''}<div data-body>${body}</div></div>`;}
export function scalingReader(link){return topic(scalingMeta,scalingSections,'A scaling law answers a resource question—not “how large should every model be?”',`
<p>Training compute can buy a larger model, a longer training stream, or a better recipe. These choices compete. A scaling law estimates their trade-off from controlled smaller runs. It is useful only when its variables, objective and extrapolation range match the proposed run.</p><p>Start with pretraining allocation. Then account for finite novelty and deployment cost. The later decomposition and coupled-surface sections explain why one fitted power law can hide several bottlenecks.</p>
${section('question','Start with the objective',`<p>Training-compute optimality means the lowest validation loss for a fixed training FLOP budget. Deployment optimality may accept more training to reduce recurring inference cost. A downstream reasoning score, a weighted domain NLL suite and general text NLL are also different objectives.</p><p>Do not call a run inefficient without saying which cost and outcome you are comparing. A small, heavily trained model can be off the pretraining frontier and still be the better product choice.</p>`)}
${section('units','Name the quantities before fitting',`${table('Keep the units and parameter convention consistent',['Symbol','Meaning','Important distinction'],[['N','Model parameters','Total versus non-embedding; active versus stored for MoE'],['D','Processed training tokens in the allocation law','Not necessarily unique tokens'],['U_D','Unique useful tokens','Deduplication and source quality affect novelty'],['C','Training FLOPs','Not elapsed time or dollars'],['B, T, K','Batch samples, optimizer steps, processed samples K=BT','Convert sequences to tokens explicitly'],['E','Fitted constant loss floor','Not measured entropy of an ideal distribution']])}${eq(String.raw`C\approx 6ND`,'Dense-transformer first approximation: about 2ND forward and 4ND backward FLOPs.')}<p>Attention length, embeddings, recomputation and other operations change this accounting. Optimizer and communication overhead change elapsed time. For MoE, active parameters approximate arithmetic, while total parameters affect memory and stored capacity. See <a href="${link('training/parallelism')}">Distributed Training →</a> and <a href="${link('models/moe')}">MoE →</a>.</p>`)}
${section('power','Read a power law above its floor',`${eq(String.raw`\begin{aligned}L(x)&=E+Ax^{-\alpha}\\\log(L-E)&=\log A-\alpha\log x\end{aligned}`,'A>0 and α>0; the straight line is reducible loss, not total loss.')}<p>A multiplicative scale increase gives a predictable fractional reduction in the reducible term. Absolute improvement diminishes. Very small runs can be noisy or unstable; very large runs can hit data or objective saturation. Fit the regime supported by observations, not all points automatically.</p><p>Two explanations are useful hypotheses. A structured data manifold can permit progressively finer approximation with capacity. A heavy-tailed distribution of skills can make common patterns arrive early and rare patterns arrive late. Neither is a settled universal mechanism. The quantization model makes the second idea explicit.</p><p>For a pure reducible power ${inlineMath(String.raw`f(x)=Ax^{-\alpha}`)}, rescaling x by λ&gt;0 multiplies f by ${inlineMath(String.raw`\lambda^{-\alpha}`)}. Power laws have long tails, scale invariance and simple resource algebra. They are useful first models, not a guarantee against characteristic scales or exponential saturation.</p>`)}
${section('kaplan','2020: capacity and sample efficiency',`<p>Kaplan et al. observed smooth loss scaling with model size, data and compute. Larger models were more sample-efficient. Their compute-allocation summary puts more growth into capacity: ${inlineMath(String.raw`N^*\propto C^{0.73}`)}, ${inlineMath(String.raw`D^*\propto C^{0.27}`)}.</p><p>A tenfold compute increase therefore gives about 5.4× parameters and 1.9× tokens under that fitted regime. This encouraged large models trained on relatively short streams. It is a result of a recipe and fitting method, not a constant of nature. ${cite('https://arxiv.org/abs/2001.08361','Kaplan et al.')}</p>`)}
${section('chinchilla','2022: balance capacity and tokens',`${eq(String.raw`L(N,D)=E+AN^{-\alpha}+BD^{-\beta}`,'An additive model of capacity and data limitations.')}<p>Chinchilla used fixed-size training curves, equal-compute sweeps and a joint parametric fit. Its empirical conclusion was much closer to equal growth in parameters and tokens. Many preceding large models had too few tokens for their training compute.</p><p>The familiar D≈20N rule gives 20B tokens for 1B parameters, 140B for 7B, and 1.4T for 70B. It is an approximate reference from that study. Different fits need not preserve a constant ratio. ${cite('https://arxiv.org/abs/2203.15556','Hoffmann et al.')}</p>`)}
${section('allocation','Derive the fixed-compute optimum',`${eq(String.raw`\begin{aligned}D&=\frac{C}{6N}\\L(N)&=E+AN^{-\alpha}+B\left(\frac C6\right)^{-\beta}N^\beta\end{aligned}`,'A larger model leaves fewer tokens under the same compute.')}<p>Differentiate with respect to N. At an interior optimum, ${inlineMath(String.raw`\alpha AN^{-\alpha}=\beta BD^{-\beta}`)}. The weighted reducible terms balance, not necessarily the raw terms or token/parameter counts.</p>${eq(String.raw`\begin{aligned}N^*&=\left(\frac{\alpha A}{\beta B}\right)^{\frac1{\alpha+\beta}}\left(\frac C6\right)^{\frac\beta{\alpha+\beta}}\\D^*&=\left(\frac{\beta B}{\alpha A}\right)^{\frac1{\alpha+\beta}}\left(\frac C6\right)^{\frac\alpha{\alpha+\beta}}\end{aligned}`,'Requires positive amplitudes/exponents and the stated unconstrained dense cost model.')}<p>When ${inlineMath(String.raw`\alpha\approx\beta`)}, both exponents approach one half. If ${inlineMath(String.raw`\alpha\ne\beta`)}, ${inlineMath(String.raw`\frac{D^*}{N^*}`)} varies as ${inlineMath(String.raw`C^{\frac{\alpha-\beta}{\alpha+\beta}}`)}. Memory limits, discrete architectures and a finite corpus can move the feasible optimum to a boundary.</p><details><summary>Small allocation implementation</summary><pre><code>def allocate(C, A, B, alpha, beta):
    N = (alpha*A/(beta*B))**(1/(alpha+beta))
    N *= (C/6)**(beta/(alpha+beta))
    return N, C/(6*N)</code></pre><p>Positive inputs only; units must match the fitted amplitudes. This does not estimate A, B or the exponents.</p></details>`)}
${section('budget-lab','Move along an equal-compute curve',lab('budget','More capacity means fewer tokens','Move the chosen allocation; inspect loss at a fixed normalized budget.','<label>Allocation<input aria-label="Compute allocation" type="range" min="0" max="50" step="1" value="25"></label><label>Outer exponent<select aria-label="Budget coupling"><option value="1">k=1 additive</option><option value="0.5">k=0.5 coupled</option><option value="1.5">k=1.5</option></select></label>',budgetBody(25),true))}
${section('counting','Why fitted frontiers disagree',`<p>Kaplan and Chinchilla used different scale ranges, training schedules, extrapolation procedures and parameter conventions. Embeddings are a large share of small models. Counting total versus non-embedding parameters changes a proxy fit; it is not a full explanation of all disagreement.</p><p>A small slope error becomes large across several orders of magnitude. Later reconciliation and replication studies are useful checks on methodology. Compare several fitting views, consistent parameter counts and a larger held-out run before choosing a final allocation.</p>`)}
${section('estimates','Convert compute into a first budget',`${budgetTable('Approximate arithmetic examples, not feasibility guarantees',['Question','Calculation','Result'],[['7B parameters, 1T tokens',inlineMath(String.raw`6\times7\times10^9\times10^{12}`),inlineMath(String.raw`4.2\times10^{22}`)+' FLOPs'],[inlineMath(String.raw`10^{23}`)+' FLOPs, 10B parameters',inlineMath(String.raw`D=\frac{C}{6N}`),'1.67T tokens'],[inlineMath(String.raw`10^{23}`)+' FLOPs under '+inlineMath(String.raw`D\approx20N`),inlineMath(String.raw`N\approx\sqrt{\frac{C}{120}}`),'28.9B parameters; 577B tokens'],['64 GPUs, 30 days, 989 TFLOP/s peak, utilization 0.35',inlineMath(String.raw`C=n\,t_{\rm seconds}\,F_{\rm peak}\,u`),inlineMath(String.raw`5.74\times10^{22}`)+' FLOPs; about 21.9B parameters and 438B tokens under the rule']])}<p>The final row multiplies GPU count, elapsed seconds, per-GPU peak FLOP/s and utilization. Use realized training throughput and recovery overhead. A peak spec times an assumed utilization is only a scenario. The original note used ${inlineMath(String.raw`5.75\times10^{22}`)} FLOPs. Direct multiplication gives ${inlineMath(String.raw`5.74221312\times10^{22}`)} FLOPs, rounded to three significant figures in this table. Both allocations round to about 21.9B parameters and 438B tokens. Long context and sparse hardware behavior require a more detailed accounting model.</p>`)}
${section('repetition','Count novelty separately from exposure',`${eq(String.raw`\begin{aligned}D&=U_D(1+R_D)\\D'&=U_D\left[1+r_D\left(1-e^{-R_D/r_D}\right)\right]\end{aligned}`,'R_D counts extra passes after the first; r_D is fitted, not a universal epoch cap.')}<p>A 2T-token unique corpus seen three times has R_D=2 and D=6T. It does not contain 6T unique tokens. For small repeats the effective-data law initially behaves like extra data. At large repeats it approaches ${inlineMath(String.raw`U_D(1+r_D)`)}.</p><p>Muennighoff et al. also discount excess model capacity relative to the compute-optimal model for the unique corpus: ${inlineMath(String.raw`R_N=\frac{N}{U_N}-1`)}. Their fitted law uses effective N′ and D′ rather than raw counts. The model-size discount applies in its defined excess-capacity regime; a negative excess ratio is not a repetition amount. ${cite('https://arxiv.org/abs/2305.16264','Data-constrained language models')}</p>${eq(String.raw`\widehat L(N,D)=E+A(N\prime)^{-\alpha}+B(D\prime)^{-\beta}`,'N′ and D′ are the fitted effective capacity and data, not raw parameter and exposure counts. This discounted law models saturation, not an explicit worsening penalty.')}`)}
${section('repeat-lab','Watch repeated tokens lose marginal value',lab('repeat','An extra pass is not an extra corpus','Both bars use the same fixed linear scale.','<label>Extra passes<input aria-label="Extra data passes" type="range" min="0" max="16" step="1" value="2"></label>',repeatBody(2),true))}
${section('penalties','Model memorization without extrapolating forever',`${eq(String.raw`\widehat L=E+AN^{-\alpha}+B[U_D(1+R_D)]^{-\beta}+P R_D^\delta\left(\frac N{U_D}\right)^\kappa`,'A different proposed law: improvement from raw exposure competes with an explicit penalty.')}<p>The final term grows with repetition and capacity relative to unique data. It can represent a local validation-loss turn upward, unlike effective-data saturation alone. P, δ and κ must be fitted. It is not an established identity or a law that every large model must overfit faster.</p><p>A positive unbounded power penalty predicts divergent loss for unlimited repetitions. Do not extrapolate that limit as fact. Compare saturation and overfitting forms on held-out repeated-data runs. Regularization can change the fitted behavior, but stronger decay can also underfit or damage rare knowledge.</p>`)}
${section('sources-data','Make repetition source-specific',`<p>Track source-level passes, exact and near duplicates, semantic redundancy, validation loss by domain and target coverage. Mathematical proofs, boilerplate, code templates and benchmark-like items have different novelty and contamination risks. Their useful epoch limits must be measured, not inferred from the labels alone.</p><p>Data-constrained means constrained by quality, diversity, rights, deduplication and coverage—not only bytes. “Clean data shifts the curve” is a hypothesis to test under a fixed evaluation. A global token count can conceal a few heavily repeated sources.</p><p>Nanbeige’s original report describes a 12.5T filtered pool, a 6.5T higher-quality subset repeated for at least two passes, and a 23T final stream. It deliberately changes the mixture during FG-WSD. That is a joint data/schedule intervention, not evidence that repeating any 6.5T corpus will have the same effect. <a href="${link('models/compact-recipes#nan4')}">Complete pipeline →</a></p><p>Tune weight decay together with repetition and model size rather than treating its effect as independent. Compare data quality at fixed N, raw D and evaluation. A higher D/N can reflect useful diverse exposure or low-novelty repetition; the ratio alone cannot distinguish them. <a href="${link('training/data#objective')}">Data mixture objectives →</a> · <a href="${link('training/data#duplicates')}">Duplicate and memorization controls →</a></p>`)}
${section('lifecycle','Change the objective, not the meaning of optimal',`${eq(String.raw`\begin{aligned}\text{Training:}\quad&\min_{N,D}L(N,D),\quad 6ND\le C_{\rm train}\\\text{Lifecycle:}\quad&\min_{N,D}\left[6ND+c_{\rm infer}(N,\text{context},\text{batch})Q\right]\\&\text{subject to }L(N,D)\le L_{\rm target}\end{aligned}`,'Q is expected served work. Actual serving cost is not simply parameter count.')}<p>Training is paid once; inference recurs. A smaller model trained longer can reach a useful quality target at lower lifecycle cost. Extra tokens beyond the pretraining frontier may still help; they are less efficient than changing capacity under that particular training-only budget.</p><p>The rough phrase “training cost ≈ inference cost” is not an optimality theorem. The optimum depends on marginal costs, demand, latency, hardware and the loss surface. Overtraining describes a reference comparison, not a promise of improved quality or a diagnosis of harmful overfitting.</p>${table('Deployment constraints can change the feasible optimum',['Constraint','What to measure','Why parameter count is insufficient'],[['Latency','Prefill and decode latency at the intended batch/context','Serial depth and kernel utilization change runtime'],['Memory / local deployment','Weights, KV cache and peak working memory','MoE active count omits stored experts'],['Recurring demand','Expected served work over the deployment lifetime','Training is paid once; serving repeats'],['Adaptation','Fine-tuning quality and cost at matched data','Heavy pretraining is not a universal adaptation gain']])}<p>These are constraints to test, not guaranteed benefits of more tokens. <a href="${link('execution/serving#economics')}">Serving economics →</a> · <a href="${link('models/compact-recipes')}">Small and on-device recipes →</a></p>`)}
${section('examples','Read heavy-training examples with their denominators',`${budgetTable('Reported training densities retained from the atlas; not controlled cross-model comparisons',['Model / regime','Reported tokens and denominator','Interpretation'],[['Llama 3 8B',inlineMath(String.raw`\frac{15\times10^{12}}{8\times10^9}\approx1{,}875`)+' TPP','Far beyond the rough 20 TPP reference; original report discussion quotes ≈200B compute-optimal tokens'],['DeepSeek-V3',inlineMath(String.raw`\frac{14.8\times10^{12}}{37\times10^9}=400`)+' active TPP','Active TPP is not a fitted dense-model optimum'],['GLM-4.5',inlineMath(String.raw`\frac{23\times10^{12}}{32\times10^9}\approx719`)+' active TPP','Stored capacity and serving behavior differ'],['MAI','100–200 TPP ablations; 500–1,000 production','Training density can change architecture rankings'],['Nanbeige4-3B',inlineMath(String.raw`\frac{23\times10^{12}}{3\times10^9}\approx7{,}667`)+' TPP','A small dense model with exceptional training investment'],['Qwen3','36T across a staged family','Do not assign one family-wide TPP without a size/stage denominator']])}<p>The Llama 3 discussion reports continuing improvement at very high token density and motivates smaller models through inference efficiency. This is not indefinite linear improvement or proof that every benchmark tracks NLL. Nanbeige’s targeted reasoning strengths also do not mean a 3B model universally beats larger models.</p><p>The Smol Training Playbook treats scaling laws as planning priors for useful small models. Epoch AI’s 2025 trend analysis reports rising tokens per active parameter and roughly 20× the Chinchilla reference in recent open models—about 400 TPP if the comparison starts at 20. These historical observations are not today’s measured ecosystem-wide ratio.</p><p>${cite('https://ai.meta.com/blog/meta-llama-3/','Meta Llama 3 announcement')} · ${cite('https://arxiv.org/abs/2412.19437','DeepSeek-V3 report')} · ${cite('https://arxiv.org/abs/2508.06471','GLM-4.5 report')} · ${cite('https://arxiv.org/abs/2505.09388','Qwen3 report')} · ${cite('https://epoch.ai/data-insights/training-tokens-per-parameter','Epoch AI: August 2025 trend')}</p><p>TPP means tokens per parameter. Dense TPP is ${inlineMath(String.raw`\frac DN`)}; active TPP is ${inlineMath(String.raw`\frac D{N_{\rm act}}`)}. GLM’s 23T is a multi-stage budget. Family/stage totals are not necessarily the same exposure for every released checkpoint.</p>`)}
${section('stages','Include the rest of the train–infer–think pipeline',`<p>A pretraining fit does not price continued pretraining, context extension, SFT, RL or reasoning tokens. High TPP can mean useful diversity or repeated low-novelty content. It does not reveal which. Long-context serving also includes cache and attention costs, not only active parameter FLOPs.</p><p>Overtraining may change adaptability; post-training behavior needs separate measurements. Choose a base model for the complete pipeline. A reasoning-time compute objective is different from minimizing pretraining NLL under 6ND. Keep those studies separate before combining their costs.</p><p>The named studies ask different questions. Sardana et al. add deployment demand to model/data allocation. Gadre et al. study overtrained loss and downstream-task prediction. Train-to-Test scaling jointly budgets model size, training tokens and repeated inference samples. Each empirical scope is distinct; none proves that a high TPP always improves adaptation.</p><p>${cite('https://arxiv.org/abs/2401.00448','Beyond Chinchilla-Optimal')} · ${cite('https://arxiv.org/abs/2403.08540','Gadre et al.: overtraining and downstream tasks')} · ${cite('https://arxiv.org/abs/2604.01411','Test-Time Scaling Makes Overtraining Compute-Optimal')} · <a href="${link('post-training/reasoning')}">Reasoning and test-time budgets →</a></p>`)}
${section('gaps','Decompose the loss before proposing a law',`<p>Su Jianlin inserts idealized training optima between achieved training loss and target-distribution loss. Let L_target be achieved target loss; L_train achieved training loss; L_best the architecture’s best training loss; and L_∞ the unrestricted training floor.</p>${eq(String.raw`L_{\rm target}=(L_{\rm target}-L_{\rm train})+(L_{\rm train}-L_{\rm best})+(L_{\rm best}-L_\infty)+L_\infty`,'Exact telescoping identity: data/generalization difference + optimization gap + architecture gap + training floor.')}<p>The identity is exact if these quantities are defined consistently. Its power-law parameterizations are hypotheses. Under nested feasible classes and true global optima, the architecture and optimization gaps are nonnegative. The target-minus-training difference need not be: a target distribution can be easier than the training set. The original general nonnegative-gap claim needed this correction.</p><p>The training floor depends on the training distribution and class convention. It is not automatically the irreducible entropy of the inaccessible ideal distribution. These gaps interact: architecture affects optimization and generalization. They are not independently measurable causes simply because they sum to loss. ${cite('https://kexue.fm/archives/11833','Deconstructing scaling laws')}</p>`)}
${section('gap-lab','Build the accounting identity',lab('gap','Add differences between nested losses','Use the signed alternative to see why the identity does not imply positive generalization.','<label>Components<input aria-label="Loss components" type="range" min="0" max="4" step="1" value="0"></label><label>Target distribution<select aria-label="Generalization case"><option value="positive">Harder target: +0.3</option><option value="negative">Easier target: −0.5</option></select></label>',gapBody(0,'positive'),true))}
${section('competing','One algebraic pattern connects the trade-offs',`${eq(String.raw`\begin{aligned}f(x)&=ax^p+bx^{-q}\\x^*&=\left(\frac{bq}{ap}\right)^{\frac1{p+q}}\\f(x^*)&=(p+q)\left(\frac{a^qb^p}{p^pq^q}\right)^{\frac1{p+q}}\end{aligned}`,'All coefficients, exponents and x positive. Differentiate or apply weighted AM–GM.')}<p>At the optimum, ${inlineMath(String.raw`pax^p=qbx^{-q}`)}. The increasing and decreasing contributions balance after weighting by slopes. Power-law inputs can therefore produce power-law optimal allocations. This mathematical closure explains recurring formulas; it does not establish that the proposed input terms describe training.</p>`)}
${section('learning-rate','Balance travel and update precision',`${eq(String.raw`\begin{aligned}F_{\rm opt}&\approx a_1(T\eta)^{-\gamma_1}+a_2B^{-\gamma_2}+a_3\eta^{\gamma_3}\\\eta^*&=\left(\frac{\gamma_1a_1T^{-\gamma_1}}{\gamma_3a_3}\right)^{\frac1{\gamma_1+\gamma_3}}\end{aligned}`,'Heuristic terms: insufficient progress, batch noise and update/discretization error.')}<p>More steps or a larger rate reduce the first term; an overly large rate increases the third. After optimizing η, combine the travel and update terms.</p>${eq(String.raw`\begin{aligned}\eta^*&\propto T^{-\frac{\gamma_1}{\gamma_1+\gamma_3}}\\F_{\rm opt}^*&\approx\widetilde a_1T^{-\widetilde\gamma_1}+a_2B^{-\gamma_2}\\\widetilde\gamma_1&=\frac{\gamma_1\gamma_3}{\gamma_1+\gamma_3}\end{aligned}`,'Positive fitted coefficients and exponents; the collapsed coefficient absorbs the optimized rate terms.')}<p>A longer horizon changes the derived frontier.</p><p>Longer runs permit a smaller optimal rate under this model. A fully tuned frontier need not retain η as an independent fit variable. This is not a guarantee that a real optimizer has these terms or remains stable at the derived rate. <a href="${link('training/optimization')}">Optimization and joint batch/LR experiments →</a></p>`)}
${section('batch','K means processed samples, not unique data',`${eq(String.raw`\begin{aligned}K&=BT,\qquad T=\frac KB\\F_{\rm opt}^*&\approx\widetilde a_1\left(\frac BK\right)^{\widetilde\gamma_1}+a_2B^{-\gamma_2}\\B^*&\propto K^{\frac{\widetilde\gamma_1}{\widetilde\gamma_1+\gamma_2}}\end{aligned}`,'A fixed exposure budget trades more precise gradients for fewer optimizer updates.')}<p>If ${inlineMath(String.raw`\gamma_1=\gamma_3=1`)} and ${inlineMath(String.raw`\gamma_2=\frac12`)}, then ${inlineMath(String.raw`\widetilde\gamma_1=\frac12`)}, ${inlineMath(String.raw`B^*\propto K^{1/2}`)}, ${inlineMath(String.raw`\eta^*\propto K^{-1/4}`)}, and the optimized gap scales as ${inlineMath(String.raw`K^{-1/4}`)}. The last rate result uses ${inlineMath(String.raw`T=\frac{K}{B^*}`)}; it does not hold at fixed B automatically.</p><p>For 1,000,000 processed sequences, B=100 gives T=10,000; B=1,000 gives T=1,000. K is unchanged. If each sequence has S fixed tokens, total processed tokens are SK. With variable lengths, sum actual valid tokens. Repeated examples count again in K, but not in unique data.</p><p>Agreement with empirical exponents is suggestive, not confirmation of the mechanism. Tune on controlled proxy runs and test a near-optimal region instead of using this as an uncalibrated batch recommendation.</p>${eq(String.raw`F_{\rm opt}^*\propto K^{-\frac{\widetilde\gamma_1\gamma_2}{\widetilde\gamma_1+\gamma_2}}`,'Requires jointly optimized rate and batch under fixed processed samples. It is not a claim for an arbitrary fixed batch.')}`)}
${section('size-optimization','Model size also changes the optimization terms',`<p>The preceding batch derivation holds architecture fixed. The loss-decomposition blog then lets N change the three coefficients, while holding the exponents fixed. This is a hypothesis, not proof that larger models necessarily introduce more gradient noise.</p>${eq(String.raw`\begin{aligned}F_{\rm opt}&\approx a_1N^{-\gamma_5}(T\eta)^{-\gamma_1}+a_2N^{\gamma_6}B^{-\gamma_2}+a_3N^{\gamma_7}\eta^{\gamma_3}\\\eta_T^*&=\left(\frac{\gamma_1a_1}{\gamma_3a_3}\right)^{\frac1{\gamma_1+\gamma_3}}T^{-\frac{\gamma_1}{\gamma_1+\gamma_3}}N^{-\frac{\gamma_5+\gamma_7}{\gamma_1+\gamma_3}}\\\Delta&=\gamma_1\gamma_3+\gamma_2(\gamma_1+\gamma_3)\\\eta^*&\propto K^{-\gamma_1\gamma_2/\Delta}N^{[\gamma_1\gamma_6-\gamma_7(\gamma_1+\gamma_2)-\gamma_5\gamma_2]/\Delta}\\B^*&\propto K^{\gamma_1\gamma_3/\Delta}N^{[\gamma_6(\gamma_1+\gamma_3)+\gamma_5\gamma_3-\gamma_7\gamma_1]/\Delta}\\F_{\rm opt}^*&\propto K^{-\gamma_1\gamma_2\gamma_3/\Delta}N^{[\gamma_1\gamma_2\gamma_7+\gamma_1\gamma_3\gamma_6-\gamma_2\gamma_3\gamma_5]/\Delta}\end{aligned}`,'Positive coefficients and positive decay exponents; K=BT. The optimum treats rate and batch as continuous, unconstrained variables.')}<p>The first rate optimum holds T and B fixed. The later expressions jointly optimize rate and batch at fixed K. At that joint optimum, each reduction balances its opposing cost. Requiring both optimal batch and optimal gap to be independent of N gives the following conditional simplification.</p>${eq(String.raw`\begin{aligned}\gamma_3\gamma_5&=\gamma_1\gamma_7,\qquad\gamma_6=0\\\gamma_1=\gamma_3&=1,\quad\gamma_2=\tfrac12\quad\Longrightarrow\\\eta^*&\propto K^{-1/4}N^{-\gamma_7},\qquad B^*\propto K^{1/2},\qquad F_{\rm opt}^*\propto K^{-1/4}\end{aligned}`,'Size independence is an extra assumption, not an empirical conclusion from this derivation.')}<p>The rate can still depend on size when batch and optimized gap do not. Assigning ${inlineMath(String.raw`\gamma_7=0.25`)} gives the ratios below. These are normalized illustrations, not measured tuning results.</p>${table('Conditional model: change one resource by 16×; other resource and coefficients fixed',['Change','Rate ratio','Batch ratio','Optimization-gap ratio'],[['Processed samples K ×16','0.5','4','0.5'],['Parameters N ×16','0.5','1','1']])}<p>Integer batches, memory limits, stable-rate ranges and schedules can move the optimum to a boundary. Calibrate the hypothesis on controlled runs before using it.</p>`)}
${section('shape','Allocate width and depth under a parameter budget',`${eq(String.raw`\begin{aligned}F_{\rm arch}&\approx a_WW^{-\gamma_W}+a_HH^{-\gamma_H},\qquad N\propto W^2H\\W^*&\propto N^{\frac{\gamma_H}{\gamma_W+2\gamma_H}}\\H^*&\propto N^{\frac{\gamma_W}{\gamma_W+2\gamma_H}}\\F_{\rm arch}^*&\propto N^{-\frac{\gamma_W\gamma_H}{\gamma_W+2\gamma_H}}\end{aligned}`,'An additive width/depth hypothesis under transformer-like counting.')}<p>With both exponents one, width and depth scale as ${inlineMath(String.raw`N^{1/3}`)}, and the gap as ${inlineMath(String.raw`N^{-1/3}`)}. This derives a shape rule from assumptions, not a proof of universally optimal transformer shapes. Kernels, depth stability, attention/FFN ratios and memory change the feasible architecture.</p>`)}
${section('compute-gaps','Balance optimized training and architecture',`${eq(String.raw`\begin{aligned}F&\approx\widehat a_1K^{-\widehat\gamma_1}+a_4N^{-\gamma_4},\qquad C\propto NK\\N^*&\propto C^{\frac{\widehat\gamma_1}{\widehat\gamma_1+\gamma_4}},\qquad K^*\propto C^{\frac{\gamma_4}{\widehat\gamma_1+\gamma_4}}\\F^*&\propto C^{-\frac{\widehat\gamma_1\gamma_4}{\widehat\gamma_1+\gamma_4}}\end{aligned}`,'The constant cost factor is suppressed in these proportionalities.')}<p>Using ${inlineMath(String.raw`\widehat\gamma_1=\frac14`)} and ${inlineMath(String.raw`\gamma_4=\frac13`)} gives ${inlineMath(String.raw`N^*\propto C^{3/7}`)}, ${inlineMath(String.raw`K^*\propto C^{4/7}`)} and ${inlineMath(String.raw`F^*\propto C^{-1/7}`)}. The near-equal allocation resembles Chinchilla. It does not prove that Chinchilla’s fitted data term is this optimization gap.</p><p>The same conditional model also predicts how tuning changes along this compute frontier. Substitute the optimized size and exposure into the preceding rate and batch laws.</p>${eq(String.raw`\begin{aligned}\eta^*&\propto (C^{4/7})^{-1/4}(C^{3/7})^{-\gamma_7}=C^{-\frac{1+3\gamma_7}{7}}\\B^*&\propto (C^{4/7})^{1/2}=C^{2/7}\\T^*&=\frac{K^*}{B^*}\propto C^{2/7}\end{aligned}`,'Requires the preceding size-independence assumptions, selected exponents and fixed dense cost per processed sample.')}<p>With the assigned size exponent 0.25, a 128× compute increase gives the following ratios. Each row changes jointly; these are not independent hyperparameter sweeps.</p>${table('Synthetic compute-frontier example; compare each quantity with its starting value',['Quantity','Ratio at compute ×128'],[['Parameters N','8'],['Processed samples K','16'],['Batch B','4'],['Optimizer steps T','4'],['Learning rate η','≈0.2973'],['Combined optimization + architecture gap','0.5']])}<p>The compute factor must stay constant across runs. Sequence length, attention cost, sparse routing, utilization and wall-clock overhead can invalidate that condition. A fitted learning-rate exponent also depends on the optimizer and schedule. This calculation is not a universal scaling recipe.</p>`)}
${section('sparsity','Stored capacity does not replace active computation',`${eq(String.raw`\begin{aligned}F_{\rm arch}&\approx a_4N_{\rm act}^{-\gamma_{\rm act}}N_{\rm total}^{-\gamma_{\rm total}}+a_8N_{\rm act}^{-\gamma_8}\\S&=\frac{N_{\rm total}}{N_{\rm act}}\\F_{\rm product}&=a_4N_{\rm act}^{-(\gamma_{\rm act}+\gamma_{\rm total})}S^{-\gamma_{\rm total}}\end{aligned}`,'The second term prevents unlimited inactive storage from replacing all active work.')}<p>Without the active-capacity penalty, a simplistic product law can make pathological trade-offs between stored capacity and active computation. At fixed N_act, increasing sparsity adds stored capacity, but it also changes routing, communication, imbalance, utilization and memory.</p>${eq(String.raw`\begin{aligned}N_{\rm eff}&=N_{\rm act}^{\frac{\gamma_{\rm act}}{\gamma_{\rm act}+\gamma_{\rm total}}}N_{\rm total}^{\frac{\gamma_{\rm total}}{\gamma_{\rm act}+\gamma_{\rm total}}}\\F_{\rm product}&=a_4N_{\rm eff}^{-(\gamma_{\rm act}+\gamma_{\rm total})}\end{aligned}`,'A weighted geometric mean under the positive-exponent product model; it does not absorb the active-capacity penalty.')}<p>This equivalent count rewrites the product term as a dense-shaped power law. It is not a measured equivalence between two architectures. If ${inlineMath(String.raw`\gamma_{\rm act}=\gamma_{\rm total}`)}, the expression reduces to ${inlineMath(String.raw`N_{\rm eff}=\sqrt{N_{\rm act}N_{\rm total}}`)}. Assigned active/total counts of 4/36 give ${inlineMath(String.raw`N_{\rm eff}=12`)}. The same product term can therefore occur at different active costs. The extra active-capacity penalty breaks that equivalence for the full gap. Routing and hardware costs remain separate.</p><p>PKM, UltraMem, Over-Encoding and Engram can be viewed as sparse retrieval capacity: select a few stored vectors instead of computing every weight. This analogy is not architectural identity. Under fixed active compute and memory, experts and retrieval can have an interior allocation if their distinct marginal improvements justify it. The exact additive model remains a hypothesis. <a href="${link('models/moe')}">Routing, balancing and expert parallelism →</a></p>`)}
${section('memory-allocation','Divide storage between experts and memory',`<p>The preceding sparse-capacity model leaves an allocation question open. At fixed active work and total storage, should extra parameters be inactive experts or retrieved vectors? Su Jianlin proposes separate power-law terms for these two sources of capacity. This is a modeling hypothesis, not evidence that any fixed mixture wins.</p><p>First count each component once. A counts dense parameters plus active experts; X counts inactive experts; M counts stored memory vectors. These are parameter counts, not bytes. In this model, A excludes retrieved vectors because they do not perform an expert matrix multiplication. Retrieval, selection and fusion still require real computation.</p>
${eq(String.raw`\begin{aligned}N_{\rm act}&=A,\qquad N_{\rm total}=A+X+M\\N_{\rm moe}&=A+X,\qquad N_{\rm mem}=A+M\\N_{\rm moe}+N_{\rm mem}&=N_{\rm total}+N_{\rm act}=S\end{aligned}`,'N_moe excludes memory; N_mem excludes inactive experts. Both include the active base A, so their sum counts that base twice.')}
<figure class="topic-scene"><svg viewBox="0 0 460 255" role="img" aria-label="Synthetic counts: eight active units, twelve inactive expert units and four memory units. Total storage is twenty-four. Expert-side count twenty and memory-side count twelve both include the same eight active units."><text x="20" y="25">One storage budget: 24 units</text><rect x="20" y="43" width="140" height="35" fill="#eadbad"/><rect x="160" y="43" width="210" height="35" fill="#bd738e"/><rect x="370" y="43" width="70" height="35" fill="#bad6fa"/><text x="40" y="67" fill="#231820">A = 8</text><text x="210" y="67" fill="#231820">X = 12</text><text x="380" y="67" fill="#231820">M = 4</text><text x="20" y="110">Expert-side count: A + X = 20</text><rect x="20" y="124" width="140" height="25" fill="#eadbad"/><rect x="160" y="124" width="210" height="25" fill="#bd738e"/><text x="20" y="184">Memory-side count: A + M = 12</text><rect x="20" y="198" width="140" height="25" fill="#eadbad"/><rect x="160" y="198" width="70" height="25" fill="#bad6fa"/></svg><figcaption>Original counting diagram with assigned units, not a model measurement. The two lower rows share A; they are not disjoint allocations.</figcaption></figure>
<p>Fixing A makes the active-capacity penalty constant. The proposed architecture gap then reduces to two decreasing terms. Moving storage toward one term reduces the other term's capacity.</p>
${eq(String.raw`\begin{aligned}F_{\rm arch}&\approx a_{4a}A^{-\gamma_{\rm act}}N_{\rm moe}^{-p}+a_{4b}A^{-\gamma_{\rm act}}N_{\rm mem}^{-q}+a_8A^{-\gamma_8}\\&=c+aN_{\rm moe}^{-p}+bN_{\rm mem}^{-q}\\N_{\rm moe}&=xS,\qquad N_{\rm mem}=(1-x)S\\f(x)&=\widetilde a x^{-p}+\widetilde b(1-x)^{-q},\quad\widetilde a=aS^{-p},\quad\widetilde b=bS^{-q}\end{aligned}`,'Positive coefficients and exponents. At fixed A, absorb its factor into a,b and its penalty into c. S is held fixed.')}
<p>The fixed-sum constraint differs from the earlier fixed-compute product constraint. Differentiation balances the marginal improvements, not the two losses themselves.</p>
${eq(String.raw`\begin{aligned}f'(x)&=-p\widetilde a x^{-p-1}+q\widetilde b(1-x)^{-q-1}\\\frac{x^{p+1}}{(1-x)^{q+1}}&=\frac{p\widetilde a}{q\widetilde b}\end{aligned}`,'The ratio on the left increases strictly from zero to infinity on (0,1). It has one unconstrained root, found by bisection.')}
<p>Physical counts add a restriction: ${inlineMath(String.raw`\frac AS\le x\le1-\frac AS`)}. Neither side can contain fewer than the active base. The unconstrained root can fall outside this interval. In that case the feasible optimum is an endpoint: all additional storage goes to one component. An interior mixture is therefore possible, not guaranteed.</p><p>For equal exponents ${inlineMath(String.raw`p=q`)}, the unconstrained root has a closed form: ${inlineMath(String.raw`x^*=\frac{r}{1+r},\quad r=(a/b)^{1/(p+1)}`)}. For unequal exponents, solve the monotone equation numerically. Real expert counts are discrete; evaluate feasible neighbors around a continuous prediction.</p>
${table('Synthetic fixed-sum example: A=8, total=24, p=q=1, a=25, b=9; omit constant c',['Extra storage','N_moe','N_mem',inlineMath(String.raw`\frac{25}{N_{\rm moe}}+\frac9{N_{\rm mem}}`)],[['All memory: X=0, M=16','8','24','3.5000'],['Mixture: X=12, M=4','20','12','2.0000'],['All inactive experts: X=16, M=0','24','8','2.1667']])}
<p>Here ${inlineMath(String.raw`r=\frac53`)} gives ${inlineMath(String.raw`x=\frac58`)} within the feasible interval ${inlineMath(String.raw`[\frac14,\frac34]`)}. The mixture is best under these assigned coefficients. Changing the coefficients can move the optimum to a boundary. Fit these terms with controlled architecture experiments before using the prediction. Equal parameter counts also need not mean equal memory bytes or runtime. ${cite('https://kexue.fm/archives/11833#%E8%AE%B0%E5%BF%86%E4%B9%8B%E5%B1%82','Source: memory-layer hypothesis')}</p>`)}
${section('epochs','A local repetition penalty gives a fragile epoch rule',`${eq(String.raw`\begin{aligned}F_{\rm data}&\approx a_9U^{-\gamma_9}+a_{10}\left(\frac KU\right)^{\gamma_{10}}\\F_{\rm opt}^*&\approx\widehat a_1K^{-\widehat\gamma_1}\\K^*&\propto U^{\frac{\gamma_{10}}{\widehat\gamma_1+\gamma_{10}}},\qquad\frac{K^*}U\propto U^{-\frac{\widehat\gamma_1}{\widehat\gamma_1+\gamma_{10}}}\end{aligned}`,'U denotes unique samples here, avoiding the overloaded D in the original decomposition.')}<p>This particular model predicts more optimal epochs for a smaller corpus. Other empirical work gives the opposite trend. Its unbounded repetition penalty is also implausible as a universal limit. Constraints such as requiring at least one full pass can clip its optimum. Keep it as a local testable hypothesis, not an epoch policy.</p>${eq(String.raw`\begin{aligned}G(K,U)&=aK^{-s}+bK^tU^{-r}\\K^*&=\left(\frac{as}{bt}U^r\right)^{\frac1{s+t}}\\\frac{K^*}{U}&\propto U^{\frac{r-s-t}{s+t}}\end{aligned}`,'Positive a,b,s,t,r. Hold unique samples U, architecture and optimized recipe fixed while choosing processed samples K. The omitted unique-data-only term does not affect this derivative.')}<p>The blog relaxes the penalty's dependence on corpus size instead of tying it to the epoch count alone. Here s controls the optimization decay, t the repetition growth, and r the corpus-size dependence. The original penalty is the special case ${inlineMath(String.raw`r=t`)}. The sign of the epoch trend now depends on r, not merely on whether repetition has a cost.</p>${table('Consequences of the generalized local model; other coefficients/exponents held fixed',['Corpus dependence','Epoch trend','Assigned example: U grows from 1 to 16'],[[inlineMath(String.raw`r<s+t`),'Optimal epochs decrease','r=1: K grows 1→4; epochs 1→0.25'],[inlineMath(String.raw`r=s+t`),'Optimal epochs stay constant','r=2: K grows 1→16; epochs 1→1'],[inlineMath(String.raw`r>s+t`),'Optimal epochs increase','r=3: K grows 1→64; epochs 1→4']])}<p>The examples assign a=b=1 and ${inlineMath(String.raw`s=t=1`)}, so ${inlineMath(String.raw`K^*=U^{r/2}`)}. These are unconstrained mathematical examples, not recommended training budgets. The first row falls below one full pass at U=16; a full-pass requirement moves that optimum to K=U. The generalized penalty still diverges with unlimited exposure. It explains how assumptions can reverse the prediction; it does not validate any trend. ${cite('https://kexue.fm/archives/11833','Source: optimal-epoch hypothesis')}</p>`)}
${section('coefficients','Test slope changes instead of assuming them',`${eq(String.raw`\begin{aligned}L_1-E_1&=A_1x^{-\alpha_1},\qquad L_2-E_2=A_2x^{-\alpha_2}\\\frac{L_1-E_1}{L_2-E_2}&=\frac{A_1}{A_2}x^{-(\alpha_1-\alpha_2)}\end{aligned}`,'Compare reducible terms; floors can dominate total-loss ratios.')}<p>The decomposition blog suggests coefficients represent engineering efficiency and exponents represent problem difficulty. Different exponents imply an unbounded relative reducible-loss advantage asymptotically. That is an argument for testing shared slopes, not proof that architecture or optimization cannot change exponents.</p><p>Scale range, task distribution and dominant bottleneck can change fitted slopes. Fit shared- and separate-slope alternatives, assess uncertainty and validate at larger held-out scales. Avoid a large combined formula with many correlated terms before nested experiments support its parts.</p>`)}
${section('coupling','2026: ask whether model and data interact',`${eq(String.raw`\begin{aligned}\text{Additive:}\quad&\frac{\partial^2L}{\partial N\,\partial D}=0\\\text{Skaling:}\quad&L=(AN^{-\alpha}+BD^{-\beta})^k+E\\&\frac{\partial^2L}{\partial N\,\partial D}=k(k-1)u^{k-2}\alpha A N^{-\alpha-1}\beta B D^{-\beta-1}\end{aligned}`,`${inlineMath(String.raw`u=AN^{-\alpha}+BD^{-\beta}`)}; positive inner parameters and k.`)}<p>The additive law forces marginal capacity value to be independent of data. Videau et al. find systematic boundary residuals and predominantly negative mixed derivatives on their main grids. They estimate derivatives using moving least squares and a differentiable Gaussian-process surrogate; small first-order cross-slopes can conceal second-order interaction.</p><p>For 0&lt;k&lt;1 the mixed derivative is negative: more data makes extra capacity more valuable, and vice versa. k=1 is additive; k&gt;1 gives the opposite cross-effect. Both first derivatives remain negative for any k&gt;0.</p><p>A negative additive interaction ${inlineMath(String.raw`GN^{-\mu}D^{-\nu}`)} can instead break monotonicity. The outer power avoids that problem. Kaplan had an outer coupling with tied inner exponents; Skaling unties them. Related forms also appear in distillation scaling. The contribution is not the discovery that no one had ever used an outer power. ${cite('https://arxiv.org/abs/2608.07222','Skaling')}</p>${eq(String.raw`\begin{aligned}\frac{\partial L}{\partial N}&=-k\alpha A N^{-\alpha-1}u^{k-1}\\\frac{\partial L}{\partial D}&=-k\beta B D^{-\beta-1}u^{k-1}\\\log\left|\frac{\partial L}{\partial N}\right|&\approx a_N\log N+g_N\log D+c_N\\\log\left|\frac{\partial L}{\partial D}\right|&\approx g_D\log N+a_D\log D+c_D\end{aligned}`,'First two rows: exact coupled-law derivatives with positive inputs/parameters. Last two: local diagnostic fits, not identities of that law.')}`)}
${section('coupling-measurement','Convert log-coordinate derivatives correctly',`<p>The numerical estimators fit a surface in log coordinates. A derivative of log loss is not a derivative of loss. Apply the chain rule before interpreting its sign.</p>${eq(String.raw`\begin{aligned}x&=\ln N,\quad y=\ln D,\quad z=\ln L,\quad L>0\\L_N&=\frac LN z_x,\qquad L_D=\frac LD z_y\\L_{ND}&=\frac L{ND}(z_{xy}+z_xz_y)\end{aligned}`,'Subscripts denote partial derivatives of a smooth positive loss surface. The product term is necessary for the mixed derivative.')}<p>Assigned local example: at N=D=L=1, take log slopes −0.2 and −0.3, and log mixed derivative −0.02. The actual mixed derivative is positive:</p>${table('Synthetic chain-rule example; values are not estimates from the paper',['Contribution','Value'],[['Log mixed derivative','−0.02'],['Product of log slopes','+0.06'],['Mixed derivative of loss','+0.04']])}<p>A negative log mixed derivative alone therefore does not establish negative model–data interaction in loss. MLS neighbourhood choices and GP kernel/noise choices also affect the estimated surface. Compare estimators and test the actual converted derivatives.</p>`)}
${section('coupling-lab','Compare marginal gains on the same surface',lab('coupling','Does data change the value of capacity?','Keep all inner parameters fixed; vary only the outer mapping.','<label>Data budget<input aria-label="Coupling data budget" type="range" min="0" max="8" step="1" value="4"></label><label>Coupling exponent<select aria-label="Coupling exponent"><option value="1">k=1 additive</option><option value="0.5">k=0.5 synergy</option><option value="1.5">k=1.5</option></select></label>',couplingBody(4,1)))}
${section('coupled-optimum','The outer exponent does not directly move the optimum',`<p>For k&gt;0, ${inlineMath(String.raw`u\mapsto u^k+E`)} is increasing. Under the same ${inlineMath(String.raw`C=6ND`)} constraint, minimizing the coupled loss is equivalent to minimizing its inner sum. The allocation formulas above therefore still apply when A, B, α and β are held fixed.</p><p>Fitting a different surface changes those inner parameters, which can move the predicted optimum. On Farseer, derivative estimates give ${inlineMath(String.raw`\frac{D^*}{N^*}\propto C^{-0.14}`)} or ${inlineMath(String.raw`C^{-0.15}`)}; Skaling predicts about −0.11 and additive Chinchilla about +0.03. On SK-Grid, ${inlineMath(String.raw`\alpha>\beta`)} instead predicts an increasing ratio. There is no universal replacement TPP number or universal decreasing trend.</p><p>In PDF Figure 6, the GP and MLS curves locate minima on smooth surrogate surfaces fitted to the measured runs. They are not directly measured optimal training runs at every compute budget. The right panel extends power-law fits outside the shaded data range; agreement there is extrapolation, not frontier validation.</p>`)}
${section('profiling','Use an L-shaped grid, then test its missing corner',`<figure class="topic-scene"><svg viewBox="0 0 430 295" role="img" aria-label="Log-spaced model and token grid: inexpensive bottom and left bands used for fitting, expensive top-right points withheld"><path d="M50 40V240H385" fill="none" stroke="#93748a"/>${Array.from({length:5},(_,d)=>Array.from({length:5},(_,n)=>`<circle cx="${80+65*n}" cy="${210-38*d}" r="7" fill="${d===0||n===0?'#bad6fa':'#bd738e'}" opacity="${d===0||n===0?1:.45}"/>`).join('')).join('')}<text x="50" y="25">More training tokens ↑</text><text x="65" y="275">More parameters →</text></svg><figcaption>Blue bands fit the law. Faded interior/corner points test it. This is grid geometry, not a measured loss surface.</figcaption></figure><p>Large-long runs dominate dense-grid compute. Sweep D at small N and N at short horizons; use the coupled form to predict the rest. Reported fitting compute falls from 5.0×10²² to 5.1×10²¹ FLOPs on Farseer and from 3.1×10²¹ to 6.5×10²⁰ on SK-Grid: approximately 10× and 5× respectively.</p><p>Both bands still need enough range to identify decay rates. Sparse fitting does not remove expensive validation. Withhold several larger-N, larger-D and far-corner runs deliberately before a frontier commitment.</p>`)}
${section('evidence','Keep the Skaling comparisons and their scope',`${residualFigure}<p>MAPE measures prediction error relative to each measured validation loss. It does not measure the loss improvement from training a model. Measured losses 2 and 4, with predictions 2.2 and 3.6, give 10% MAPE.</p>${eq(String.raw`\operatorname{MAPE}=\frac{100}{m}\sum_{i=1}^{m}\frac{|\widehat L_i-L_i|}{L_i}`,'m is the number of evaluated runs; Lᵢ is positive measured loss and L̂ᵢ is predicted loss. The output is a percentage.')}<p>Table 1 reports means and standard deviations across five cross-validation folds. The deviations below are not confidence intervals. The far-extrapolation sets contain only seven Farseer runs and three SK-Grid runs. Small far-corner samples limit how broadly these gains can be interpreted. The grids use a prescribed hyperparameter policy, not a new exhaustive tuning sweep at every point.</p><p> The study records Farseer’s 404 configurations, mainly 100M–6.4B parameters and 1B–512B tokens, with larger-model checks to 25B; SK-Grid’s 134M–4.9B appendix models and checks to 10.8B; 117 code-domain runs; and 245 replicated Chinchilla configurations. These are not present-day frontier-sized measurements.</p>${table('Paper Table 1: full-grid MAPE %, mean ± standard deviation over five folds; Chinchilla → Skaling',['Regime','Farseer','SK-Grid'],[['Interpolation','0.77 ±0.04 → 0.41 ±0.05','0.81 ±0.14 → 0.33 ±0.11'],['Larger N','1.48 ±0.03 → 0.47 ±0.03','0.83 ±0.11 → 0.39 ±0.05'],['Larger D','1.98 ±0.08 → 0.88 ±0.06','1.44 ±0.03 → 0.58 ±0.07'],['Far extrapolation','2.46 ±0.19 → 2.31 ±0.18','5.17 ±0.28 → 0.70 ±0.39']])}<p>The figure comparison favors Skaling on 76% of configurations, with median 2.2× error advantage. The boundary gains matter more than interpolation fit. On SK-Grid far extrapolation, full/L-shaped Chinchilla give 5.17%/14.63%; full/L-shaped Skaling give 0.70%/1.15%.</p><p>A fixed-ratio test uses 14 Farseer D/N rays and eight high-compute held-out points per ray, 112 total. MAPE: Chinchilla 2.34%, Farseer law 0.80%, independent per-ray power fits 0.99%, Skaling 0.60%. Independent per-ray fits are slightly better on the near-optimal-ratio subset, where each recipe receives its own fit. They cannot answer joint allocation questions.</p><p>Code and replication sets have weaker coupling: ${inlineMath(String.raw`k\approx0.77\text{–}0.90`)} versus roughly ${inlineMath(String.raw`k\approx0.31\text{–}0.45`)} in the main grids. Hyperparameter policies can change the observed surface. Extrapolation to 2×10²⁵ FLOPs is far beyond measured budgets around 10²². Version-one SK-Grid run accounting also differs between section 4.1 (134/15 sizes) and appendix E (125/14). Retain that inconsistency rather than choosing an unverified count.</p>`)}
${section('sk-grid-recipe','Keep the measured surface tied to its recipe',`<p>Appendix E specifies the SK-Grid policy used to generate the measured surface. Its StepLaw coefficients were refitted for this setup.</p>${eq(String.raw`\begin{aligned}B_{\rm tokens}&=896.07\,F^{0.231}\\\eta_{\rm peak}&=0.0709\,F^{-0.4303}D^{0.2785}\end{aligned}`,'F is per-token compute in FLOPs per token; D is the training token budget. B here counts tokens, not the sequences used in the earlier optimization example.')}<p>The reported peak rate increases with token budget. This is a recipe-specific prescription, not the fixed-K optimum derived above. Changing units changes the numerical coefficients.</p>${table('SK-Grid fixed settings; reported conditions, not universal defaults',['Control','Setting'],[['Tokenizer / context','Llama 3; vocabulary 128,256; 2,048 tokens'],['Width / depth range','672–3,264 dimensions; 7–34 layers'],['Data / validation target','60% DCLM-Edu web, 30% code, 10% math; held-out split of this mixture'],['Optimizer','AdamW; moments (0.9, 0.95); weight decay 0.1; gradient clipping 0.1'],['Schedule','Cosine; 10% warmup; final learning rate 0.000001']])}<p>Compute caps give larger models fewer token horizons: the smallest row has 16 budgets, the largest only one. This staircase is not a full Cartesian grid. Keep the separate version-one run-count discrepancy visible rather than resolving it by assumption.</p>`)}
${section('floor','The fitted floor is not measured entropy',`<p>In the original Farseer fit, Skaling shifts E from about 0.45 to 0.03. This does not demonstrate near-zero irreducible loss. k and E can compensate over an unsaturated range; the observations constrain their sum better than their individual interpretation.</p><p>Subtract losses for dominated pairs—where one run has more parameters, more data and lower loss—to remove E from the fitting objective. Appendix F reports Farseer far-extrapolation MAPE of 2.46%→0.79% for Chinchilla and about 2.32%→1.55% for Skaling using this alternative. Some apparent boundary failure is therefore tied to floor identification, not only zero coupling.</p><p>Table 9 uses a separate fitting run, so its 2.32% baseline can differ from Table 1’s 2.31%. The paper states this explicitly; the difference is not merely reported precision. On SK-Grid the coupled advantage remains larger. Compare fitting objectives before claiming that one mechanism fully explains another law’s failure.</p><p>Fit the shape from ordered differences, then recover the constant from residuals. In Appendix F, X denotes per-token compute F, not total training compute C.</p>${eq(String.raw`\begin{aligned}r(X,D)&=(AX^{-\alpha}+BD^{-\beta})^k\\\widehat L_j-\widehat L_i&=r(X_j,D_j)-r(X_i,D_i)\\\widehat E&=\operatorname{median}_j\,[L_j-r(X_j,D_j)]\end{aligned}`,`Pairs require ${inlineMath(String.raw`X_i\ge X_j`)}, ${inlineMath(String.raw`D_i\ge D_j`)} and ${inlineMath(String.raw`L_i<L_j`)}. The displayed difference is predicted; measured differences are fitting targets. Recover the floor after fitting the shape; k is the outer exponent, not a run index.`)}<p>Pair selection also reweights the observations. Dominated-pair fitting is therefore not simply the same objective with one nuisance parameter removed. It can worsen extrapolation: Farseer L-shape Skaling far-error rises from 1.57% to 5.87% in Table 9.</p>`)}
${section('fitting','Design a fit that can fail honestly',`<p>Keep tokenizer, data mixture, optimizer policy, schedule, context, precision and parameter convention controlled or explicitly modeled. Preserve loss precision. Inspect rising/flattened curves and failed runs instead of discarding them without explaining the selection.</p><p>The Skaling fit uses Huber error in log loss with transition ${inlineMath(String.raw`\delta=0.05`)}, log-amplitudes, analytic gradients with bounded L-BFGS-B, basin hopping with Sobol initialization and 2,000 restarts, with CMA-ES as a cross-check. Its bounds are ${inlineMath(String.raw`A,B\in[10^{-6},10^7]`)}, ${inlineMath(String.raw`\alpha,\beta,k\in[0.01,2]`)}, ${inlineMath(String.raw`E\in[0,3]`)}. They are fit constraints, not physical constants.</p><p>Compare additive and coupled models under the same objective/optimizer. Report folds, parameter variation, signed residual maps, interpolation, single-axis and far-corner errors separately. Test intended D/N rays and floor-free alternatives. More parameters do not guarantee a stronger baseline: the nine-parameter Farseer form is also harder to fit.</p><p>Use nested experiments: tune optimization at fixed data/architecture; study architecture near a tuned regime; study data under controlled optimization; combine only supported terms. Validation NLL is smoother than many generation scores, but the final target still needs downstream checks and uncertainty. A high in-sample R² is not an extrapolation certificate.</p>${table('Three scaling questions require separate controls',['Question','Variables','Transfer check'],[['Model/data allocation','N,D and processed budget','Validate a larger held-out run'],['Hyperparameter scaling','Learning rate,batch,warmup,decay','Retune or calibrate their horizon dependence'],['Parametrization transfer','Width and weight/update scaling','Check that a proxy optimizer setting transfers']])}<p>A correctly sized model can still be poorly optimized. Fit the smallest supported gap model first, derive its constrained optimum, then test new runs near that prediction. Reject terms that imply impossible limits.</p>`)}
${section('ladders','Compare curves, not one proxy winner',`${eq(String.raw`\begin{aligned}f(C)&=AC^{-\alpha}+E\\\mathrm{EG}&=\frac{f^{-1}(L')}{C'}=\frac1{C'}\left(\frac A{L'-E}\right)^{1/\alpha}\end{aligned}`,'Defined only for achieved L′>E; use the same evaluation and cost convention.')}<p>MAI compares architecture/data candidates on scaling ladders at a matched training density. ${inlineMath(String.raw`\mathrm{EG}=1.3`)} means the fitted baseline needs 30% more cost to match the candidate. ${inlineMath(String.raw`\mathrm{EG}_{\mathrm{FLOPs}}`)} and ${inlineMath(String.raw`\mathrm{EG}_{\mathrm{Time}}`)} separate modeling efficiency from actual implementation speed. Recovery and goodput affect the latter.</p><p>The original internal NLL target is 0.5 Coding +0.175 STEM +0.175 Math +0.1 General +0.05 Multilingual. It encodes priorities; it is not neutral general quality. A STEM-heavy mixture winning at small scale but losing to a code-heavier one at larger scale illustrates why rankings must be revalidated.</p><p>Keep ablation and production TPP distinct. A proxy design win need not survive heavier training, a different mixture or a different kernel implementation. The full report also discusses deduplication, epoch caps and deterministic recovery; those belong with data/run design rather than being reduced to one scaling coefficient.</p>`)}
${section('rl','RL scaling is a different resource problem',`<p>MiMo-V2.6 treats rollout/training compute, environment breadth and grader compute as coupled resources. This is not a literal additive pretraining loss law. Narrow tasks or indistinguishable passing rewards can make more trajectories redundant.</p><p>The original report section records 1,568 prompts ×16 trajectories =25,088 per step, 2.7–3.7B training tokens and roughly 110K–150K sequence lengths. Pro cost shares are 43.8% rollout, 43.5% training and 12.7% grading; reported total RL costs are about $2.6M Pro and $0.9M Flash. Grading is a substantial workload, not free post-processing.</p><p>Harness and environment diversity change which competence is trained. The original four-harness coding experiment raises mean held-out-harness pass rate from about 50% to 66%; that is an interface-diversity result, not proof that 6ND predicts RL return. The task/environment/verifier distribution and asynchronous collection are part of the scope. <a href="${link('training/frontier-recipes#mimo')}">Complete MiMo RL note →</a></p>`)}
${section('sources','References and connected notes',`<p>${cite('https://arxiv.org/abs/2001.08361','Kaplan')} · ${cite('https://arxiv.org/abs/2203.15556','Chinchilla')} · ${cite('https://arxiv.org/abs/2406.12907','Reconciling Kaplan and Chinchilla')} · ${cite('https://arxiv.org/abs/2404.10102','Chinchilla replication')} · ${cite('https://arxiv.org/abs/2303.13506','Quantization model')}</p><p>${cite('https://arxiv.org/abs/2305.16264','Data-constrained scaling')} · ${cite('https://arxiv.org/abs/2205.10487','Repeated data')} · ${cite('https://arxiv.org/abs/2605.01640','Prescriptive data-constrained scaling')} · ${cite('https://kexue.fm/archives/11833','Loss decomposition')} · ${cite('https://arxiv.org/abs/2608.07222','Skaling')} · ${cite('https://arxiv.org/abs/2506.10972','Farseer')} · ${cite('https://arxiv.org/abs/2502.08606','Distillation scaling')}</p><p>${cite('https://lilianweng.github.io/posts/2026-06-24-scaling-laws/','Scaling Laws, Carefully: synthesis')}</p><p>${cite('https://huggingface.co/spaces/HuggingFaceTB/smol-training-playbook','Smol Training Playbook')} · ${cite('https://microsoft.ai/wp-content/uploads/2026/06/main_20260602_2.pdf','MAI-Thinking-1 report')}</p><p>Connected owners: <a href="${link('execution/performance#capacity')}">Capacity planning →</a> · <a href="${link('training/practice')}">Run design →</a> · <a href="${link('models/transformers#budget-design')}">Transformer shapes →</a> · <a href="${link('training/optimization')}">Hyperparameter and parametrization transfer →</a> · <a href="${link('training/frontier-recipes#mai-measurement')}">MAI scaling ladders →</a></p>`)}
`);}
export function mountScaling(scope=document){mountTopic(scope,scalingMeta.slug,article=>{for(const name of ['budget','repeat','gap','coupling']){const scene=article.querySelector(`[data-scaling-lab="${name}"]`),slider=scene.querySelector('input'),select=scene.querySelector('select'),draw=()=>{const n=Number(slider.value),body=name==='budget'?budgetBody(n,Number(select.value)):name==='repeat'?repeatBody(n):name==='gap'?gapBody(n,select.value):couplingBody(n,Number(select.value));scene.querySelector('[data-body]').innerHTML=body;};if(name!=='coupling'){const playback=rangePlayback(article,scene,draw,14000);select?.addEventListener('change',()=>{playback.stop();draw();});}else slider.addEventListener('input',draw);if(name==='coupling')select.addEventListener('change',draw);draw();}});}
scalingMeta.searchText=scalingReader(()=> '').replace(/<[^>]*>/g,' ');
export {budgetBody as scalingBudgetBody};
